  border-top: 1px solid rgb(226 222 255 / 14%);
}

.hero-facts div { display: grid; gap: 1px; }
.hero-facts dt {
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.hero-facts dd {
  margin: 0;
  color: var(--paper-soft);
  font-size: 0.84rem;
  font-weight: 600;
}

/* ==========================================================================
   Landing sections
   ========================================================================== */

.positioning {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: var(--space-7);
  width: min(1180px, calc(100% - 2rem));
  margin: var(--space-8) auto 0;
  padding: clamp(1.5rem, 3vw, 2.5rem);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(135deg, rgb(20 28 47 / 74%), rgb(9 13 23 / 82%)),
    var(--surface-1);
  box-shadow: var(--shadow-2);
}

.positioning h2 {
  margin-top: var(--space-2);
  color: var(--paper);
  font-size: clamp(1.7rem, 3vw, 2.5rem);
}

.positioning-copy > p:last-child {
  max-width: 62ch;
  margin-top: var(--space-3);
  color: var(--text-muted);
}

.positioning-points {
  display: grid;
  gap: var(--space-3);
  align-content: center;
}

.positioning-points li {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(240 235 225 / 4%);
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.positioning-points svg { flex: none; color: var(--amber); margin-top: 0.12rem; }
.positioning-points strong { color: var(--text); }

.section {
  width: min(1180px, calc(100% - 2rem));
  margin: 0 auto;
  padding: clamp(3.5rem, 8vw, 6.5rem) 0;
}

.section + .section,
.section + .final-cta {
  border-top: 1px solid var(--border);
}

.section-heading {
  max-width: 760px;
  margin-bottom: var(--space-6);
}

.section-heading h2 {
  margin-top: var(--space-2);
  color: var(--paper);
  font-size: clamp(1.9rem, 3.8vw, 3rem);
}

.section-heading p:last-child {
  max-width: 66ch;
  margin-top: var(--space-3);
  color: var(--text-muted);
}

/* Usage modes */

.mode-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-5);
}

.mode-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: clamp(1.3rem, 2.4vw, 2rem);
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(160deg, rgb(27 37 64 / 72%), rgb(9 13 23 / 90%));
  box-shadow: var(--shadow-2);
}

.mode-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--mode-accent, var(--violet)), transparent);
  opacity: 0.9;
}

.mode-spectral { --mode-accent: var(--spectral); }
.mode-amber { --mode-accent: var(--amber); }

.mode-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.mode-card h3 {
  color: var(--paper);
  font-size: clamp(1.45rem, 2.2vw, 1.9rem);
}

.mode-card > p { color: var(--text-muted); }

.check-list {
  display: grid;
  gap: var(--space-2);
  color: var(--text-muted);
  font-size: 0.9rem;
}

.check-list li {
  display: flex;
  gap: var(--space-2);
  align-items: flex-start;
}

.check-list svg {
  flex: none;
  margin-top: 0.25rem;
  color: var(--status-positive);
}

.mode-card .text-link { margin-top: auto; }

/* ==========================================================================
   Spirits
   ========================================================================== */

.spirit-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-4);
}

.spirit-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, rgb(20 28 47 / 72%), rgb(9 13 23 / 92%));
  box-shadow: var(--shadow-1);
}

.spirit-card-art {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 240px;
  padding: var(--space-4);
  background:
    radial-gradient(circle at 50% 58%, color-mix(in srgb, var(--spirit-glow) 18%, transparent), transparent 56%),
    linear-gradient(180deg, rgb(27 37 64 / 42%), transparent);
  border-bottom: 1px solid var(--border);
}

.spirit-card-art .spirit {
  width: min(170px, 72%);
  height: auto;
}

.spirit-card-number {
  position: absolute;
  top: var(--space-3);
  right: var(--space-4);
  color: rgb(240 235 225 / 16%);
  font-family: var(--font-display);
  font-size: 2.4rem;
  line-height: 1;
}

.spirit-card-copy {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
}

.spirit-card-copy h3 {
  color: var(--paper);
  font-size: 1.6rem;
}

.spirit-role {
  color: var(--spirit-accent);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.spirit-card-copy > p {
  color: var(--text-muted);
  font-size: 0.88rem;
  line-height: 1.6;
}

.spirit-work {
  padding-top: var(--space-2);
  border-top: 1px dashed var(--border);
  color: var(--text-dim) !important;
  font-size: 0.8rem !important;
}

.state-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: var(--space-2);
}

.state-list li {
  padding: 0.16rem 0.45rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.spirit-card-oracle { --spirit-accent: var(--amber); --spirit-glow: var(--amber); }
.spirit-card-architect { --spirit-accent: var(--cyan); --spirit-glow: var(--cyan); }
.spirit-card-maker { --spirit-accent: var(--mint); --spirit-glow: var(--mint); }
.spirit-card-witness { --spirit-accent: var(--violet); --spirit-glow: var(--violet); }

.spirit-card .spirit-role { color: var(--spirit-accent); }

/* Character SVG palette and states */

.spirit {
  overflow: visible;
  filter: drop-shadow(0 12px 22px rgb(0 0 0 / 38%));
}

.spirit-oracle { --spirit-accent: var(--amber); --spirit-glow: var(--amber); }
.spirit-architect { --spirit-accent: var(--cyan); --spirit-glow: var(--cyan); }
.spirit-maker { --spirit-accent: var(--mint); --spirit-glow: var(--mint); }
.spirit-witness { --spirit-accent: var(--violet); --spirit-glow: var(--violet); }

.spirit-metal { fill: #d8d5e5; stroke: rgb(10 14 24 / 52%); stroke-width: 1; }
.spirit-dark { fill: #232a3e; }
.metal-line { stroke: #cfcbe0; stroke-width: 2; stroke-linecap: round; }

.spirit-body,
.oracle-halo,
.architect-cloak,
.maker-body,
.witness-body {
  transform-box: fill-box;
  transform-origin: center;
}

.oracle-ring {
  fill: none;
  stroke: rgb(255 208 138 / 26%);
  stroke-width: 0.9;
  stroke-dasharray: 2 5;
}

.oracle-glass { stroke: rgb(255 255 255 / 32%); stroke-width: 1; }
.oracle-mask { fill: #171326; stroke: rgb(255 208 138 / 40%); stroke-width: 0.8; }
.oracle-eye { fill: var(--amber-bright); }
.oracle-pupil { fill: #2a1a08; }
.oracle-wisp {
  fill: none;
  stroke: rgb(255 208 138 / 34%);
  stroke-width: 1.4;
  stroke-linecap: round;
}

.oracle-listen path {
  fill: none;
  stroke: rgb(159 231 255 / 44%);
  stroke-width: 1.2;
  stroke-linecap: round;
}

.oracle-question circle {
  fill: var(--cyan);
  opacity: 0.9;
}

.architect-tail {
  fill: rgb(159 231 255 / 16%);
  stroke: rgb(159 231 255 / 34%);
  stroke-width: 1;
}

.architect-cloak {
  stroke: rgb(203 216 255 / 28%);
  stroke-width: 1;
}

.architect-arm {
  fill: none;
  stroke: #b9c6ee;
  stroke-width: 2.2;
  stroke-linecap: round;
}

.architect-arm-b { stroke: rgb(159 231 255 / 68%); }
.architect-arm-c { stroke: rgb(185 164 255 / 62%); }
.architect-joint { fill: var(--cyan); }
.architect-tip { fill: #dbe7ff; opacity: 0.85; }

.architect-sheet path:first-child {
  fill: rgb(159 231 255 / 8%);
  stroke: rgb(159 231 255 / 34%);
  stroke-width: 0.8;
}

.blueprint-line { stroke: rgb(159 231 255 / 30%); stroke-width: 0.7; }
.blueprint-dot { fill: var(--cyan); }

.architect-seal path {
  fill: rgb(185 164 255 / 14%);
  stroke: var(--violet);
  stroke-width: 1;
  stroke-linejoin: round;
}

.maker-body { stroke: rgb(232 236 255 / 44%); stroke-width: 1.2; }
.maker-visor { fill: #141a29; stroke: rgb(159 231 255 / 24%); stroke-width: 1; }
.maker-eye { fill: var(--cyan); }
.maker-smile { fill: none; stroke: rgb(159 231 255 / 52%); stroke-width: 1.4; stroke-linecap: round; }
.maker-arm {
  fill: none;
  stroke: #aeb8da;
  stroke-width: 3;
  stroke-linecap: round;
  transform-box: fill-box;
  transform-origin: top center;
}
.maker-hand { fill: none; stroke: #cfd5ea; stroke-width: 1.6; stroke-linecap: round; }
.maker-belt { fill: #3a435f; stroke: rgb(232 236 255 / 24%); stroke-width: 0.8; }
.maker-pouch { fill: rgb(143 227 184 / 16%); stroke: rgb(143 227 184 / 44%); stroke-width: 0.8; }
.maker-wrench { fill: none; stroke: #cfd5ea; stroke-width: 1.8; stroke-linecap: round; }

.maker-sparks path,
.maker-sparks circle {
  fill: none;
  stroke: var(--amber-bright);
  stroke-width: 1.4;
  stroke-linecap: round;
}

.maker-permission circle {
  fill: rgb(255 208 138 / 8%);
  stroke: var(--amber);
  stroke-width: 1.4;
}

.maker-permission path {
  fill: none;
  stroke: var(--amber-bright);
  stroke-width: 2;
  stroke-linecap: round;
}

.maker-blocked path:first-child {
  fill: rgb(255 180 168 / 10%);
  stroke: var(--rose);
  stroke-width: 1.4;
}

.maker-blocked path:last-child { stroke: var(--rose); stroke-width: 2.2; }

.maker-success circle,
.maker-success path {
  fill: none;
  stroke: var(--mint);
  stroke-width: 1.4;
  stroke-linecap: round;
}

.maker-success path:nth-child(2) { stroke-width: 3; }

.witness-wing path:first-child { stroke: rgb(239 234 255 / 34%); stroke-width: 0.8; }
.wing-vein { fill: none; stroke: rgb(239 234 255 / 26%); stroke-width: 0.7; stroke-linecap: round; }
.wing-eye { fill: rgb(199 182 255 / 18%); stroke: rgb(199 182 255 / 48%); stroke-width: 0.8; }
.witness-antenna,
.witness-body {
  fill: none;
  stroke: rgb(226 220 255 / 58%);
  stroke-width: 1.4;
  stroke-linecap: round;
}
.witness-body { fill: rgb(20 16 34 / 74%); }
.witness-lens circle { fill: none; stroke: rgb(199 182 255 / 38%); stroke-width: 1; }
.witness-lens circle:nth-child(2) { stroke: rgb(159 231 255 / 52%); }
.witness-pupil { fill: var(--violet); stroke: none !important; }
.witness-shutter {
  fill: rgb(199 182 255 / 6%);
  stroke: rgb(199 182 255 / 24%);
  stroke-width: 0.6;
}
.witness-lens-line { stroke: var(--cyan); stroke-width: 1.2; stroke-dasharray: 3 3; }
.witness-stamp path:first-child {
  fill: rgb(199 182 255 / 10%);
  stroke: var(--violet);
  stroke-width: 1.2;
}
.witness-stamp path:last-child { fill: none; stroke: rgb(199 182 255 / 54%); stroke-width: 1.2; }
.witness-evidence path:first-child { fill: rgb(240 235 225 / 7%); stroke: rgb(199 182 255 / 46%); stroke-width: 1; }
.evidence-line { stroke: rgb(199 182 255 / 40%); stroke-width: 0.8; }
.witness-warning path:first-child { fill: rgb(255 208 138 / 7%); stroke: var(--amber); stroke-width: 1.2; }
.witness-warning path:last-child { fill: none; stroke: var(--amber-bright); stroke-width: 1.6; stroke-linecap: round; }

/* State groups are hidden by default and revealed by their state class. */
.oracle-listen,
.oracle-question,
.architect-seal,
.maker-sparks,
.maker-permission,
.maker-blocked,
.maker-success,
.witness-evidence,
.witness-warning,
.witness-stamp,
.witness-lens-line {
  opacity: 0;
}

.spirit.is-listening .oracle-listen,
.spirit.is-clarification .oracle-question,
.spirit.is-approval .architect-seal,
.spirit.is-building .maker-sparks,
.spirit.is-permission .maker-permission,
.spirit.is-blocked .maker-blocked,
.spirit.is-success .maker-success,
.spirit.is-scanning .witness-lens-line,
.spirit.is-evidence .witness-evidence,
.spirit.is-warning .witness-warning,
.spirit.is-stamp .witness-stamp {
  opacity: 1;
}

.spirit.is-clarification .oracle-mask { stroke: var(--cyan); }
.spirit.is-warning .witness-lens circle { stroke: var(--amber); }
.spirit.is-blocked .maker-eye { fill: var(--rose); }
.spirit.is-permission .maker-eye { fill: var(--amber-bright); }
.spirit.is-approval .architect-arm-b { stroke: var(--violet); }
.spirit.is-drawing .architect-sheet { transform: rotate(-2deg); }

@media (prefers-reduced-motion: no-preference) {
  .spirit-body,
  .architect-compass,
  .witness-body {
    animation: spirit-float 7s ease-in-out infinite;
  }
  .spirit-architect .architect-compass { animation-delay: -2s; }
  .spirit-maker .spirit-body { animation-delay: -3.4s; }
  .spirit-witness .witness-body { animation-delay: -1.2s; }

  .oracle-halo { animation: spirit-breathe 5.6s ease-in-out infinite; }
  .spirit.is-listening .oracle-ring-a { animation: spirit-ripple 2.4s ease-out infinite; }
  .spirit.is-listening .oracle-ring-b { animation: spirit-ripple 2.4s 1.2s ease-out infinite; }
  .spirit.is-listening .oracle-listen { animation: spirit-shimmer 2.6s ease-in-out infinite; }
  .spirit.is-clarification .oracle-question circle:nth-child(2) { animation: spirit-shimmer 1.8s ease-in-out infinite; }
  .spirit.is-clarification .oracle-question circle:nth-child(3) { animation: spirit-shimmer 1.8s 0.3s ease-in-out infinite; }
  .spirit.is-drawing .architect-arm-b { animation: architect-draw 2.8s ease-in-out infinite; transform-box: fill-box; transform-origin: top center; }
  .spirit.is-drawing .architect-sheet { animation: blueprint-in 3.4s ease-in-out infinite; }
  .spirit.is-approval .architect-seal { animation: seal-glow 2.6s ease-in-out infinite; }
  .spirit.is-building .maker-sparks { animation: spark-flicker 0.7s steps(2, end) infinite; }
  .spirit.is-building .maker-arm-right { animation: maker-tap 1.1s ease-in-out infinite; }
  .spirit.is-permission .maker-permission { animation: permission-pulse 2.4s ease-in-out infinite; }
  .spirit.is-success .maker-success { animation: success-pulse 2.8s ease-in-out infinite; }
  .spirit.is-scanning .witness-lens-line { animation: witness-scan 3s ease-in-out infinite; }
  .spirit.is-warning .witness-warning { animation: warning-pulse 1.8s ease-in-out infinite; }
  .spirit.is-stamp .witness-stamp { animation: stamp-thump 3s ease-in-out infinite; }
}

@keyframes spirit-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

@keyframes spirit-breathe {
  0%, 100% { opacity: 0.86; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.015); }
}

@keyframes spirit-ripple {
  0% { opacity: 0.8; transform: scale(0.9); }
  100% { opacity: 0; transform: scale(1.18); }
}

@keyframes spirit-shimmer {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 1; }
}

@keyframes architect-draw {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(7deg); }
}

@keyframes blueprint-in {
  0%, 100% { opacity: 0.75; transform: translateY(0); }
  50% { opacity: 1; transform: translateY(-1px); }
}

@keyframes seal-glow {
  0%, 100% { opacity: 0.7; transform: scale(0.96); }
  50% { opacity: 1; transform: scale(1.04); }
}

@keyframes spark-flicker {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

@keyframes maker-tap {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(-6deg); }
}

@keyframes permission-pulse {
  0%, 100% { opacity: 0.55; transform: scale(0.97); }
  50% { opacity: 1; transform: scale(1.03); }
}

@keyframes success-pulse {
  0%, 100% { opacity: 0.72; transform: scale(0.98); }
  50% { opacity: 1; transform: scale(1.02); }
}

@keyframes witness-scan {
  0%, 100% { transform: translateY(-9px); opacity: 0.35; }
  50% { transform: translateY(9px); opacity: 1; }
}

@keyframes warning-pulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

@keyframes stamp-thump {
  0%, 80%, 100% { transform: translateY(0); opacity: 0.7; }
  86% { transform: translateY(3px); opacity: 1; }
  92% { transform: translateY(0); }
}

/* ==========================================================================
   Demo teaser and demo page
   ========================================================================== */

