.demo-honesty h2 { margin-top: var(--space-2); color: var(--paper); font-size: 1.25rem; }
.demo-honesty ul { display: grid; gap: var(--space-2); margin-top: var(--space-3); color: var(--text-muted); font-size: 0.86rem; }
