}

.demo-main-art {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  min-height: 340px;
  padding: var(--space-5);
  border-right: 1px solid var(--border);
  background:
    radial-gradient(circle at 50% 52%, rgb(139 164 255 / 18%), transparent 62%),
    rgb(5 7 13 / 44%);
}

