.demo-main-copy .demo-buttons { margin: var(--space-5) 0 0; }

.demo-inspector-section { padding: var(--space-7) 0; border-bottom: 1px solid var(--border); }
.demo-gallery-section { padding: var(--space-7) 0; border-bottom: 1px solid var(--border); }

.state-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-5);
}

.state-gallery-group {
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 52%);
}

.state-gallery-group > h3 { color: var(--paper); font-size: 1.35rem; }
