  border-radius: var(--radius-sm);
  background: rgb(5 7 13 / 46%);
  text-align: center;
}

.state-gallery-group .spirit { width: 84px; margin: 0 auto; }
.state-gallery-label { color: var(--paper); font-size: 0.78rem; font-weight: 700; }
.state-gallery-description { color: var(--text-dim); font-size: 0.68rem; line-height: 1.45; }

.recovery-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
}

.recovery-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}

.recovery-card h3 { color: var(--paper); font-size: 1.25rem; }
.recovery-card p { color: var(--text-muted); font-size: 0.88rem; }

.demo-bottom-cta {
  display: grid;
  justify-items: center;
  gap: var(--space-3);
  margin-top: var(--space-7);
  padding: clamp(2rem, 5vw, 3.5rem);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: radial-gradient(circle at 50% 0%, rgb(243 182 109 / 14%), transparent 64%), rgb(14 20 34 / 52%);
  text-align: center;
}

.demo-bottom-cta h2 { color: var(--paper); font-size: clamp(1.8rem, 3.5vw, 2.7rem); }
.demo-bottom-cta p { max-width: 54ch; color: var(--text-muted); }
.final-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); justify-content: center; margin-top: var(--space-3); }

/* ==========================================================================
   Status chips and surfaces
   ========================================================================== */

.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.2rem 0.55rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: rgb(5 7 13 / 44%);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.64rem;
  letter-spacing: 0.04em;
  line-height: 1.5;
  text-transform: uppercase;
  white-space: nowrap;
}

.status-dot {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgb(255 255 255 / 5%);
}

.status-chip[data-tone="positive"] { border-color: rgb(143 227 184 / 34%); color: var(--status-positive); }
.status-chip[data-tone="active"] { border-color: rgb(159 231 255 / 30%); color: var(--status-active); }
.status-chip[data-tone="warning"] { border-color: rgb(255 208 138 / 36%); color: var(--status-warning); }
.status-chip[data-tone="danger"] { border-color: rgb(255 180 168 / 38%); color: var(--status-danger); }
.status-chip[data-tone="neutral"] { color: var(--status-neutral); }

/* ==========================================================================
   Controls preview / Run Inspector
   ========================================================================== */

.controls-grid,
.setup-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: var(--space-5);
  align-items: start;
}

.controls-copy { display: grid; gap: var(--space-3); }

.control-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}

.control-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--border-amber);
  border-radius: var(--radius-sm);
  background: rgb(243 182 109 / 8%);
  color: var(--amber);
}

.control-card h3 { color: var(--paper); font-family: var(--font-ui); font-size: 0.98rem; font-weight: 700; letter-spacing: 0; }
.control-card p { grid-column: 2; margin-top: 2px; color: var(--text-muted); font-size: 0.86rem; }
.fixture-note { color: var(--text-dim); font-size: 0.78rem; font-style: italic; }

.run-inspector {
  overflow: hidden;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(180deg, rgb(20 28 47 / 78%), rgb(5 7 13 / 96%));
  box-shadow: var(--shadow-2);
}

.inspector-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-4) var(--space-3);
  border-bottom: 1px solid var(--border);
  background: rgb(5 7 13 / 42%);
}

.inspector-head h2 { margin-top: var(--space-1); color: var(--paper); font-size: 1.4rem; }
.inspector-badge {
  padding: 0.2rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.inspector-note { padding: var(--space-3) var(--space-4); color: var(--text-dim); font-size: 0.8rem; border-bottom: 1px solid var(--border); }

.inspector-block { padding: var(--space-4); border-bottom: 1px solid var(--border); }
.inspector-block:last-child { border-bottom: 0; }
.inspector-block h3 {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.run-list,
.evidence-list,
.permission-list,
.transcript-list { display: grid; gap: var(--space-2); margin-top: var(--space-3); }

.run-row,
.evidence-row {
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-left: 2px solid var(--border-strong);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: rgb(5 7 13 / 36%);
}

.run-row[data-status="SUCCEEDED"],
.run-row[data-status="PASS"] { border-left-color: var(--status-positive); }
.run-row[data-status="FAILED"],
.run-row[data-status="FAIL"],
.run-row[data-status="CANCELLED"] { border-left-color: var(--status-danger); }
.run-row[data-status="UNKNOWN"],
.run-row[data-status="WAITING_PERMISSION"] { border-left-color: var(--status-warning); }
.run-row[data-status="RUNNING"],
.run-row[data-status="QUEUED"] { border-left-color: var(--status-active); }

.run-row-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
.run-result { margin-top: var(--space-2); color: var(--text); font-size: 0.82rem; overflow-wrap: anywhere; }
.run-session { margin-top: var(--space-2); overflow-wrap: anywhere; }
.run-limitation { margin-top: var(--space-1); color: var(--text-dim); font-size: 0.74rem; }
.evidence-check { color: var(--violet); font-family: var(--font-mono); font-size: 0.76rem; }

.permission-list li {
  display: grid;
  gap: 2px;
  padding: var(--space-2) 0;
  border-bottom: 1px dashed var(--border);
}
.permission-list li:last-child { border-bottom: 0; }
.permission-name { color: var(--text); font-size: 0.84rem; font-weight: 600; }
.permission-detail { color: var(--text-dim); font-size: 0.76rem; }

.inspector-footnote {
  margin-top: var(--space-3);
  padding-top: var(--space-3);
  border-top: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 0.74rem;
}

.inspector-recovery {
  margin-top: var(--space-3);
  padding: var(--space-3);
  border: 1px solid var(--border-amber);
  border-radius: var(--radius-sm);
  background: rgb(243 182 109 / 7%);
}
.inspector-recovery p { color: var(--text-muted); font-size: 0.8rem; }
.inspector-recovery .action { margin-top: var(--space-2); }

/* ==========================================================================
   Recommendation preview
   ========================================================================== */

.recommendation-table {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}

.recommendation-row {
  display: grid;
  grid-template-columns: minmax(150px, 0.9fr) minmax(160px, 1fr) minmax(170px, 1fr) minmax(240px, 1.4fr);
  gap: var(--space-3);
  min-width: 820px;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  align-items: center;
  color: var(--text-muted);
  font-size: 0.84rem;
}

.recommendation-row:last-child { border-bottom: 0; }
.recommendation-head {
  background: rgb(5 7 13 / 48%);
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.recommendation-idea { color: var(--paper); font-weight: 600; }
.recommendation-path { color: var(--amber-bright); font-family: var(--font-mono); font-size: 0.76rem; }
.recommendation-permission { color: var(--text-dim); font-size: 0.78rem; }

/* ==========================================================================
   Setup
   ========================================================================== */

.setup-copy {
  padding: var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}
.setup-copy h3 { color: var(--paper); font-size: 1.35rem; }
.setup-copy .check-list { margin-top: var(--space-4); }
.setup-copy > p { margin-top: var(--space-4); color: var(--text-muted); font-size: 0.88rem; }
.setup-copy .text-link { margin-top: var(--space-3); }

.setup-tabs {
  overflow: hidden;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--surface-terminal);
  box-shadow: var(--shadow-2);
}

.setup-tablist {
  display: flex;
  gap: 2px;
  padding: var(--space-2) var(--space-2) 0;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  background: rgb(14 20 34 / 74%);
}

.setup-tab {
  flex: none;
  min-height: 44px;
  padding: 0.45rem 0.8rem;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  background: transparent;
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.setup-tab[aria-selected="true"] {
  border-color: var(--border);
  background: var(--surface-terminal);
  color: var(--amber-bright);
}

.setup-panel { padding: var(--space-4); }
.setup-panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.setup-panel-head h3 { margin-top: var(--space-1); color: var(--paper); font-size: 1.18rem; }
.setup-note { margin-top: var(--space-3); color: var(--text-dim); font-size: 0.8rem; }

.copy-button {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 40px;
  padding: 0 0.7rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: rgb(240 235 225 / 4%);
  color: var(--text-muted);
  font-size: 0.76rem;
}

.command-block {
  margin: var(--space-3) 0 0;
  padding: var(--space-3) var(--space-4);
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: #04070c;
  color: var(--cyan);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  line-height: 1.7;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.command-block code { font: inherit; }
.setup-source { padding: 0 var(--space-4) var(--space-4); color: var(--text-dim); font-size: 0.72rem; }

/* ==========================================================================
   Privacy, FAQ, final CTA, footer
   ========================================================================== */

.privacy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
}

.privacy-card {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: linear-gradient(150deg, rgb(20 28 47 / 62%), rgb(9 13 23 / 76%));
}

.privacy-number {
  color: rgb(185 164 255 / 44%);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}
.privacy-card h3 { margin-top: var(--space-2); color: var(--paper); font-size: 1.3rem; }
.privacy-card p { margin-top: var(--space-2); color: var(--text-muted); font-size: 0.88rem; }

.faq-list { display: grid; gap: var(--space-2); }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 48%);
}

.faq-item summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: 58px;
  padding: var(--space-3) var(--space-4);
  color: var(--paper);
  font-size: 0.98rem;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}

.faq-item summary::-webkit-details-marker { display: none; }

.faq-mark {
  position: relative;
  width: 16px;
  height: 16px;
  flex: none;
}
.faq-mark::before,
.faq-mark::after {
  content: "";
  position: absolute;
  inset: 50% 0 auto;
  height: 1.5px;
  background: var(--amber);
  transform: translateY(-50%);
}
.faq-mark::after { transform: translateY(-50%) rotate(90deg); transition: transform var(--dur-base) var(--ease-standard); }
.faq-item[open] .faq-mark::after { transform: translateY(-50%) rotate(0deg); }
.faq-item p { max-width: 78ch; padding: 0 var(--space-4) var(--space-4); color: var(--text-muted); font-size: 0.9rem; }

.final-cta {
  position: relative;
  display: grid;
  justify-items: center;
  gap: var(--space-3);
  width: min(1180px, calc(100% - 2rem));
  margin: var(--space-8) auto;
  padding: clamp(2rem, 6vw, 4.5rem);
  overflow: hidden;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-xl);
  background:
    radial-gradient(circle at 50% 18%, rgb(243 182 109 / 18%), transparent 36rem),
    radial-gradient(circle at 50% 100%, rgb(109 91 208 / 20%), transparent 34rem),
    linear-gradient(180deg, rgb(20 28 47 / 84%), rgb(5 7 13 / 96%));
  text-align: center;
  box-shadow: var(--shadow-3);
}

.final-cta h2 { max-width: 18ch; color: var(--paper); font-size: clamp(2rem, 4.6vw, 3.6rem); }
.final-cta > p:not(.eyebrow) { max-width: 58ch; color: var(--text-muted); }
.final-spirits { display: flex; align-items: flex-end; justify-content: center; gap: clamp(0.2rem, 2vw, 1.4rem); margin-bottom: var(--space-2); }
.final-spirits .spirit { width: clamp(64px, 8vw, 104px); height: auto; opacity: 0.94; }

.site-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  width: min(1180px, calc(100% - 2rem));
  margin: 0 auto;
  padding: var(--space-6) 0 var(--space-7);
  border-top: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 0.78rem;
}
.site-footer p { max-width: 46ch; }
.site-footer nav { display: flex; flex-wrap: wrap; gap: var(--space-3); }
.site-footer nav a { color: var(--text-muted); text-decoration: none; min-height: 44px; display: inline-flex; align-items: center; }
.site-footer nav a:hover { color: var(--text); }

/* ==========================================================================
   Dialog
   ========================================================================== */

.setup-dialog {
  width: min(680px, calc(100% - 2rem));
  max-height: min(90vh, 820px);
  padding: 0;
  overflow: auto;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  background: linear-gradient(160deg, rgb(20 28 47 / 98%), rgb(5 7 13 / 99%));
  color: var(--text);
  box-shadow: var(--shadow-3);
}

.setup-dialog::backdrop {
  background: rgb(2 4 9 / 78%);
  backdrop-filter: blur(6px);
}

.dialog-surface { position: relative; padding: clamp(1.25rem, 4vw, 2.2rem); }
.dialog-close { position: absolute; top: var(--space-3); right: var(--space-3); }
.dialog-surface h2 { padding-right: 3rem; margin-top: var(--space-2); color: var(--paper); font-size: clamp(1.5rem, 3vw, 2rem); }
.dialog-surface > p { margin-top: var(--space-3); color: var(--text-muted); font-size: 0.9rem; }
.dialog-steps { display: grid; gap: var(--space-4); margin-top: var(--space-5); counter-reset: dialog-step; }
.dialog-steps > li { padding-left: var(--space-5); border-left: 1px solid var(--border-violet); counter-increment: dialog-step; }
.dialog-step-title { display: block; color: var(--paper); font-weight: 700; font-size: 0.95rem; }
.dialog-step-title::before { content: counter(dialog-step) ". "; color: var(--amber); font-family: var(--font-mono); }
.dialog-steps p { margin-top: var(--space-2); color: var(--text-muted); font-size: 0.84rem; }
.dialog-note {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-5);
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: rgb(240 235 225 / 4%);
  color: var(--text-dim);
  font-size: 0.78rem;
}
.dialog-note svg { flex: none; color: var(--amber); margin-top: 0.1rem; }
.dialog-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-5); }

/* ==========================================================================
   Workshop
   ========================================================================== */

.workshop-shell { min-height: 100vh; }
.workshop { width: min(1440px, calc(100% - 2rem)); margin: 0 auto; padding: var(--space-5) 0 var(--space-8); }
.workshop-titlebar { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-4); min-height: 150px; padding: var(--space-4) var(--space-2) var(--space-3); }
.workshop-title-copy { display: grid; gap: var(--space-1); }
.workshop-stage-name { color: var(--paper); font-family: var(--font-display); font-size: clamp(1.35rem, 2.4vw, 2rem); }
.workshop-character { width: 132px; flex: none; opacity: 0.95; }
.workshop-character .spirit { width: 100%; height: auto; }

.stage-strip {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, rgb(20 28 47 / 74%), rgb(9 13 23 / 82%));
